import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, JOB_SELECT, rowToJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const port = Number(process.env.PORT ?? 3000);

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  let length = 0;
  for await (const chunk of req) {
    const b = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    length += b.length;
    if (length > 100_000) throw new Error('too_large');
    chunks.push(b);
  }
  return Buffer.concat(chunks).toString('utf8');
}

async function handler(req: IncomingMessage, res: ServerResponse): Promise<void> {
  let pathname: string;
  try { pathname = new URL(req.url ?? '/', 'http://localhost').pathname; }
  catch { error(res, 404, 'not_found', 'Route not found.'); return; }

  if (pathname === '/') {
    if (req.method !== 'GET') { error(res, 405, 'method_not_allowed', 'Method not allowed.'); return; }
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    if (req.method !== 'GET') { error(res, 405, 'method_not_allowed', 'Method not allowed.'); return; }
    const hb = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id=1').get() as {seen_at:number}|undefined;
    send(res, 200, { status: 'ok', worker: hb && Date.now() - Number(hb.seen_at) <= 3000 ? 'up' : 'down' }); return;
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const rows = db.prepare(`${JOB_SELECT} ORDER BY created_at DESC, rowid DESC`).all() as Record<string,unknown>[];
      send(res, 200, { jobs: rows.map(rowToJob) }); return;
    }
    if (req.method !== 'POST') { error(res, 405, 'method_not_allowed', 'Method not allowed.'); return; }

    const fields: {field:string;message:string}[] = [];
    const contentType = req.headers['content-type'];
    if (!contentType || !/^application\/json(?:\s*;|\s*$)/i.test(contentType)) fields.push({field:'body',message:'Content-Type must be application/json.'});
    let raw = '';
    let bodyRead = true;
    try { raw = await readBody(req); }
    catch { bodyRead = false; fields.push({field:'body',message:'Request body is too large or could not be read.'}); }
    let body: unknown;
    let parsed = false;
    if (bodyRead) {
      try { body = JSON.parse(raw); parsed = true; } catch { fields.push({field:'body',message:'Body must be valid JSON.'}); }
    }
    let input: unknown, steps: unknown, failAttempts: unknown;
    if (parsed) {
      if (!body || typeof body !== 'object' || Array.isArray(body)) fields.push({field:'body',message:'Body must be a JSON object.'});
      else {
        const obj = body as Record<string,unknown>;
        for (const k of Object.keys(obj)) if (!['input','steps','failAttempts'].includes(k)) fields.push({field:k,message:'Unknown field.'});
        input = obj.input;
        steps = Object.hasOwn(obj,'steps') ? obj.steps : 5;
        failAttempts = Object.hasOwn(obj,'failAttempts') ? obj.failAttempts : 0;
        if (typeof input !== 'string') fields.push({field:'input',message:'Must be a string.'});
        else if (input.length < 1 || input.length > 1000 || input.trim().length === 0) fields.push({field:'input',message:'Must contain 1 to 1000 characters and not be only whitespace.'});
        if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({field:'steps',message:'Must be an integer from 1 to 20.'});
        if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({field:'failAttempts',message:'Must be an integer from 0 to 5.'});
      }
    }
    const idem = req.headers['idempotency-key'];
    const key = Array.isArray(idem) ? idem[0] : idem;
    if (key !== undefined && (Array.isArray(idem) || !/^[A-Za-z0-9_-]{1,128}$/.test(key))) fields.push({field:'Idempotency-Key',message:'Must match ^[A-Za-z0-9_-]{1,128}$.'});
    if (fields.length) { error(res, 400, 'invalid_request', 'The request is invalid.', fields); return; }

    const payload = JSON.stringify({input, steps, failAttempts});
    db.exec('BEGIN IMMEDIATE');
    try {
      if (key !== undefined) {
        const old = db.prepare(`${JOB_SELECT} WHERE idempotency_key=?`).get(key) as Record<string,unknown>|undefined;
        if (old) {
          db.exec('COMMIT');
          if (old.payload === payload) send(res, 200, rowToJob(old));
          else error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
          return;
        }
      }
      const id = randomUUID(); const now = new Date().toISOString();
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,result_output,error,created_at,updated_at,idempotency_key,payload,retry_at)
        VALUES(?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, ?, 0)`)
        .run(id, input as string, steps as number, failAttempts as number, now, now, key ?? null, payload);
      const row = db.prepare(`${JOB_SELECT} WHERE id=?`).get(id) as Record<string,unknown>;
      db.exec('COMMIT'); send(res, 201, rowToJob(row));
    } catch (e) { db.exec('ROLLBACK'); throw e; }
    return;
  }

  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') { error(res, 405, 'method_not_allowed', 'Method not allowed.'); return; }
    let id: string; try { id = decodeURIComponent(match[1]); } catch { error(res,404,'not_found','Job not found.'); return; }
    const row = db.prepare(`${JOB_SELECT} WHERE id=?`).get(id) as Record<string,unknown>|undefined;
    if (!row) { error(res, 404, 'not_found', 'Job not found.'); return; }
    send(res, 200, rowToJob(row)); return;
  }
  error(res, 404, 'not_found', 'Route not found.');
}

const server = createServer((req,res) => { void handler(req,res).catch(() => { if (!res.headersSent) error(res,500,'internal_error','Internal server error.'); else res.destroy(); }); });
server.listen(port, () => console.log(`server listening on ${port}`));
const shutdown = () => { server.close(() => { db.close(); }); };
process.on('SIGTERM', shutdown); process.on('SIGINT', shutdown);

