import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, JOB_SELECT } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row can only be left behind by a worker that died mid-attempt.
// Count that attempt as consumed and make it eligible for the normal retry path.
const nowIso = new Date().toISOString();
db.prepare(`UPDATE jobs SET status=CASE WHEN attempts>=3 THEN 'failed' ELSE 'queued' END,
  error=CASE WHEN attempts>=3 THEN 'transient failure' ELSE NULL END,
  result_output=NULL, progress_completed=0, retry_at=0, updated_at=? WHERE status='running'`).run(nowIso);

console.log('worker started');
try {
  while (!stopping) {
    const now = Date.now();
    db.prepare('INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at').run(now);
    db.exec('BEGIN IMMEDIATE');
    let job: Record<string,unknown>|undefined;
    try {
      job = db.prepare(`${JOB_SELECT} WHERE status='queued' AND retry_at<=? ORDER BY created_at ASC,rowid ASC LIMIT 1`).get(now) as Record<string,unknown>|undefined;
      if (job) {
        db.prepare(`UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0,
          result_output=NULL,error=NULL,updated_at=? WHERE id=? AND status='queued'`).run(new Date().toISOString(), String(job.id));
      }
      db.exec('COMMIT');
    } catch (e) { db.exec('ROLLBACK'); throw e; }
    if (!job) { await sleep(100); continue; }

    const attempt = Number(job.attempts) + 1;
    const steps = Number(job.steps);
    if (attempt <= Number(job.fail_attempts)) {
      // Simulate a dependency failure before any step has completed.
      if (attempt >= 3) {
        db.prepare(`UPDATE jobs SET status='failed',error='transient failure',result_output=NULL,updated_at=? WHERE id=? AND status='running'`)
          .run(new Date().toISOString(), String(job.id));
      } else {
        db.prepare(`UPDATE jobs SET status='queued',error=NULL,retry_at=?,updated_at=? WHERE id=? AND status='running'`)
          .run(Date.now() + 500, new Date().toISOString(), String(job.id));
      }
      continue;
    }

    let interrupted = false;
    for (let step = 1; step <= steps; step++) {
      await sleep(100);
      if (stopping) { interrupted = true; break; }
      db.prepare(`UPDATE jobs SET progress_completed=?,updated_at=? WHERE id=? AND status='running'`)
        .run(step, new Date().toISOString(), String(job.id));
    }
    if (interrupted) break;
    db.prepare(`UPDATE jobs SET status='completed',result_output=?,error=NULL,progress_completed=steps,updated_at=? WHERE id=? AND status='running'`)
      .run(String(job.input).toUpperCase(), new Date().toISOString(), String(job.id));
  }
} finally {
  db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run();
  db.close();
}

