16	  <h1>Job tracker</h1>
17	  <form data-testid="job-form" id="job-form">
18	    <label>Input <input data-testid="job-input" id="job-input" name="input" type="text" required></label>
19	    <label>Steps <input data-testid="job-steps" id="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
20	    <label>Fail attempts <input data-testid="job-fail-attempts" id="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
21	    <button data-testid="job-submit" type="submit">Submit job</button>
22	    <div data-testid="form-error" id="form-error" role="alert"></div>
23	  </form>
24	  <h2>Jobs</h2>
25	  <div data-testid="job-list" id="job-list" aria-live="polite"></div>
26	  <script>
27	    const form = document.querySelector('[data-testid="job-form"]');
28	    const errorRegion = document.querySelector('[data-testid="form-error"]');
29	    const list = document.querySelector('[data-testid="job-list"]');
30	    const input = document.querySelector('[data-testid="job-input"]');
31	    const steps = document.querySelector('[data-testid="job-steps"]');
32	    const failAttempts = document.querySelector('[data-testid="job-fail-attempts"]');
33	    form.addEventListener('submit', async event => {
34	      event.preventDefault(); errorRegion.textContent = '';
35	      try {
36	        const response = await fetch('/api/jobs', {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({input:input.value,steps:Number(steps.value),failAttempts:Number(failAttempts.value)})});
37	        const body = await response.json();
38	        if (!response.ok) {
39	          const fields = body.error?.fields || [];
40	          errorRegion.textContent = [body.error?.message || 'Submission failed.', ...fields.map(f => `${f.field}: ${f.message}`)].join(' ');
41	        } else { input.value = ''; await refresh(); }
42	      } catch { errorRegion.textContent = 'Could not submit the job. Please try again.'; }
43	    });
44	    function el(tag, testid, text) {
45	      const node = document.createElement(tag); node.dataset.testid = testid;
46	      if (text !== undefined) node.textContent = text;
47	      return node;
48	    }
49	    async function refresh() {
50	      try {
51	        const response = await fetch('/api/jobs'); if (!response.ok) return;
52	        const {jobs} = await response.json();
53	        list.replaceChildren(...jobs.map(job => {
54	          const item = el('article','job-item'); item.className = 'job'; item.dataset.jobId = job.id;
55	          const title = el('h3','job-title',job.input); item.append(title);
56	          const status = el('span','job-status',job.status); item.append(status);
57	          const progress = el('span','job-progress',`${job.progress.completed}/${job.progress.total}`); progress.className = 'meta'; item.append(' · ',progress);
58	          const result = el('div','job-result',job.result?.output || job.error || ''); item.append(result);
59	          return item;
60	        }));
61	      } catch { /* The next poll will refresh after a brief network interruption. */ }
62	    }
63	    refresh(); setInterval(refresh, 500);
64	  </script>
